{
  "title": "祠堂的秘密",
  "scene": "你来到一座古老的祠堂前，大门紧闭，周围弥漫着一股阴冷的气息。祠堂前有一块石碑，上面刻着模糊不清的文字，隐约提到‘月圆之夜，先祖归来’。门缝里透出一丝微光，似乎有人在内。左侧有一棵老槐树，树根盘虬，树干上挂着一个旧灯笼。这时，你听到远处传来一阵敲锣声，似乎是在警告什么。",
  "goal": "找到进入祠堂的方法，解开先祖归来之谜",
  "clue": "石碑上的文字和敲锣声",
  "choices": [
    {
      "id": "A",
      "text": "敲门询问",
      "outcome": "你敲了敲门，里面传来一阵低沉的声音，门缓缓打开。你走进祠堂，发现里面空无一人，但桌上有一本泛黄的日记。日记中提到敲锣声是祖先的警告，但你已经错过了最佳进入时间。你只能在下个月圆之夜再次尝试。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "点燃灯笼",
      "outcome": "你取下灯笼并点燃，突然祠堂的大门自动打开，里面透出更加明亮的光芒。你走进祠堂，发现墙上挂满了先祖的画像，每张画上的眼睛似乎都在注视着你。你感受到一种神秘的力量，似乎解开了某种古老的仪式。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "躲在树后观察",
      "outcome": "你躲在老槐树后，观察祠堂的动静。敲锣声越来越响，突然祠堂的大门猛地关闭，发出震耳欲聋的响声。你感到一阵寒意，似乎激怒了某种不知名的力量。你不得不花费一些时间平复心情，才能继续前进。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
